import React, { useState } from 'react';
import { Menu, X, LayoutDashboard } from 'lucide-react';
import academyLogo from '../assets/logovighnaviacademy.png';

export default function Navbar({ activeScreen, setActiveScreen }) {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const navLinks = [
    { name: 'Home', screen: 'home' },
    { name: 'Career Guidance', screen: 'guidance' },
    { name: 'Workshops', screen: 'workshops' },
    { name: 'Courses', screen: 'courses' },
    { name: 'Internships', screen: 'internships' },
    { name: 'B.Tech Projects', screen: 'btech-projects' },
    { name: 'M.Tech Projects', screen: 'mtech-projects' },
    { name: 'About', screen: 'about' },
    { name: 'Contact', screen: 'contact' },
  ];

  const handleNav = (screen) => {
    setActiveScreen(screen);
    setMobileMenuOpen(false);
  };

  return (
    <header className="sticky top-0 z-40 bg-black/95 backdrop-blur-md border-b border-neutral-800 text-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
        {/* Brand / Logo */}
        <div 
          onClick={() => handleNav('home')} 
          className="cursor-pointer flex items-center space-x-3 group"
        >
          <img
            src={academyLogo}
            alt="Vighnavi Academy Logo"
            className="h-10 w-auto object-contain transition-transform duration-200 group-hover:scale-105"
            onError={(e) => {
              e.currentTarget.style.display = 'none';
              if (e.currentTarget.nextSibling) {
                e.currentTarget.nextSibling.style.display = 'flex';
              }
            }}
          />
          <div className="hidden w-10 h-10 rounded-xl bg-white text-black font-extrabold text-lg items-center justify-center border border-neutral-300">
            VA
          </div>
          <div>
            <span className="text-xl font-extrabold tracking-tight text-white block">
              Vighnavi Academy
            </span>
            <p className="text-[11px] text-neutral-400 tracking-wider uppercase font-medium">
              Wisdom • Knowledge • Success
            </p>
          </div>
        </div>

        {/* Desktop Navigation Links */}
        <nav className="hidden xl:flex items-center space-x-1">
          {navLinks.map((link) => {
            const isActive = activeScreen === link.screen;
            return (
              <button
                key={link.screen}
                onClick={() => handleNav(link.screen)}
                className={`px-3 py-2 rounded-lg text-sm font-semibold transition-colors duration-150 ${
                  isActive
                    ? 'bg-white text-black border border-white shadow-sm'
                    : 'text-neutral-300 hover:text-white hover:bg-neutral-900'
                }`}
              >
                {link.name}
              </button>
            );
          })}
        </nav>

        {/* Desktop Dashboard Button */}
        <div className="hidden xl:flex items-center space-x-3">
          <button
            onClick={() => handleNav('dashboard')}
            className="flex items-center space-x-2 bg-white hover:bg-neutral-200 text-black px-4 py-2.5 rounded-xl font-bold text-sm border border-white transition-all transform active:scale-95 shadow-md shadow-white/10"
          >
            <LayoutDashboard className="w-4 h-4 text-black" />
            <span>Dashboard</span>
          </button>
        </div>

        {/* Mobile Action Controls */}
        <div className="xl:hidden flex items-center space-x-2">
          <button
            onClick={() => handleNav('dashboard')}
            className={`p-2 rounded-lg border transition-colors ${
              activeScreen === 'dashboard'
                ? 'bg-white text-black border-white'
                : 'bg-neutral-900 text-white border-neutral-700 hover:bg-neutral-800'
            }`}
            aria-label="Dashboard"
          >
            <LayoutDashboard className="w-5 h-5" />
          </button>
          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="p-2 rounded-lg bg-neutral-900 border border-neutral-700 text-neutral-300 hover:text-white hover:bg-neutral-800 transition-colors"
            aria-label="Toggle navigation menu"
          >
            {mobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6 text-white" />}
          </button>
        </div>
      </div>

      {/* Mobile Drawer Dropdown */}
      {mobileMenuOpen && (
        <div className="xl:hidden bg-black border-b border-neutral-800 px-4 pt-2 pb-6 space-y-1">
          {navLinks.map((link) => {
            const isActive = activeScreen === link.screen;
            return (
              <button
                key={link.screen}
                onClick={() => handleNav(link.screen)}
                className={`w-full text-left px-4 py-3 rounded-lg text-sm font-semibold transition-colors ${
                  isActive
                    ? 'bg-white text-black border border-white'
                    : 'text-neutral-300 hover:text-white hover:bg-neutral-900'
                }`}
              >
                {link.name}
              </button>
            );
          })}
        </div>
      )}
    </header>
  );
}
